// This file is hand written and is not regenerated by `go generate
// ./internal/ent`: the one write of a stored fact's keyed columns, which the
// generated builders cannot express, since the schema makes every one of
// them immutable (schema/fact.go, fact_coverage.go, fact_observation.go).
//
// It exists for one operation: a change of the Controller's facts key with
// both keys live (internal/facts/entstore's rekey.go), which rewrites the
// token a fact is found by, its keyed hash, its chain link and the keys it
// names, and the tokens and digests its device's coverages and observations
// hold, all inside the caller's transaction. Every write here is a
// compare-and-swap on what the caller read: a row that no longer holds it
// fails the call with ErrFactRekeyRaced, and the caller rolls the whole
// transaction back. internal/archtest's TestOnlyTheRekeyRewritesFactKeys
// keeps every call to these methods inside the re-key's own two functions in
// entstore, so the immutability the schema states still holds for every
// other writer.
//
// Beside them is the lock that keeps a re-key and a gather of one device
// apart on PostgreSQL (LockFactsOfDevice), which the generated client cannot
// take either.
package ent

import (
	"context"
	stdsql "database/sql"
	"encoding/json"
	"errors"
	"fmt"

	"entgo.io/ent/dialect"
	entsql "entgo.io/ent/dialect/sql"

	"github.com/Subject-Void-LLC/the-pleiades/internal/ent/fact"
	"github.com/Subject-Void-LLC/the-pleiades/internal/ent/factcoverage"
	"github.com/Subject-Void-LLC/the-pleiades/internal/ent/factobservation"
)

// ErrFactRekeyRaced marks a re-key write that found its row changed since it
// was read: another transaction re-keyed the device first. The caller rolls
// back and reads the device again.
var ErrFactRekeyRaced = errors.New("ent: a stored fact changed while it was being re-keyed")

// FactKeyed is the columns of one Fact row a change of the facts key
// rewrites: what the row is found by, its keyed hash, the keys it names, and
// for a stable row its chain link.
type FactKeyed struct {
	// KeyToken is the key_token column.
	KeyToken string
	// Hash is the hash column, the fact's keyed hash.
	Hash string
	// KeyedBy is the keyed_by column, the identity of the keys.
	KeyedBy string
	// Chained is true for a stable row, whose chain_prev and chain are
	// written; a volatile row's chain columns are left as they are (null).
	Chained bool
	// ChainPrev and Chain are the row's chain link, when Chained.
	ChainPrev string
	Chain     string
}

// RekeyFact rewrites the keyed columns of the Fact row id, which belongs to
// the device whose database ID is device, from was to now, inside tx. It is
// a compare-and-swap: the row must still hold was's token, hash and keys, or
// nothing is written and the error is ErrFactRekeyRaced.
func (tx *Tx) RekeyFact(ctx context.Context, id, device int, was, now FactKeyed) error {
	b := entsql.Dialect(tx.driver.Dialect()).Update(fact.Table).
		Set(fact.FieldKeyToken, now.KeyToken).
		Set(fact.FieldHash, now.Hash).
		Set(fact.FieldKeyedBy, now.KeyedBy)
	if now.Chained {
		b = b.Set(fact.FieldChainPrev, now.ChainPrev).Set(fact.FieldChain, now.Chain)
	}
	b = b.Where(entsql.And(
		entsql.EQ(fact.FieldID, id),
		entsql.EQ(fact.DeviceColumn, device),
		entsql.EQ(fact.FieldKeyToken, was.KeyToken),
		entsql.EQ(fact.FieldHash, was.Hash),
		entsql.EQ(fact.FieldKeyedBy, was.KeyedBy),
	))
	return tx.rekeyOne(ctx, b, "fact")
}

// RekeyFactCoverage rewrites the FactCoverage row id, of the device whose
// database ID is device, from the digest wasDigest to digest and the token
// lists stable and volatile, inside tx: a compare-and-swap on the digest, as
// RekeyFact is on the keys. The lists are encoded as the generated builders
// encode a JSON field.
func (tx *Tx) RekeyFactCoverage(ctx context.Context, id, device int, wasDigest, digest string, stable, volatile []string) error {
	stableJSON, err := json.Marshal(stable)
	if err != nil {
		return fmt.Errorf("ent: encoding a re-keyed coverage: %w", err)
	}
	volatileJSON, err := json.Marshal(volatile)
	if err != nil {
		return fmt.Errorf("ent: encoding a re-keyed coverage: %w", err)
	}
	b := entsql.Dialect(tx.driver.Dialect()).Update(factcoverage.Table).
		Set(factcoverage.FieldDigest, digest).
		// json.RawMessage is what sqlgraph hands the driver for a JSON field.
		Set(factcoverage.FieldStable, json.RawMessage(stableJSON)).
		Set(factcoverage.FieldVolatile, json.RawMessage(volatileJSON)).
		Where(entsql.And(
			entsql.EQ(factcoverage.FieldID, id),
			entsql.EQ(factcoverage.DeviceColumn, device),
			entsql.EQ(factcoverage.FieldDigest, wasDigest),
		))
	return tx.rekeyOne(ctx, b, "coverage")
}

// RekeyFactObservations points every FactObservation of the device whose
// database ID is device that names the coverage wasDigest at digest instead,
// inside tx, and says how many it changed.
func (tx *Tx) RekeyFactObservations(ctx context.Context, device int, wasDigest, digest string) (int64, error) {
	query, args := entsql.Dialect(tx.driver.Dialect()).Update(factobservation.Table).
		Set(factobservation.FieldCoverage, digest).
		Where(entsql.And(
			entsql.EQ(factobservation.FieldDeviceID, device),
			entsql.EQ(factobservation.FieldCoverage, wasDigest),
		)).
		Query()
	var res stdsql.Result
	if err := tx.driver.Exec(ctx, query, args, &res); err != nil {
		return 0, fmt.Errorf("ent: re-keying observations: %w", err)
	}
	n, err := res.RowsAffected()
	if err != nil {
		return 0, fmt.Errorf("ent: re-keying observations: %w", err)
	}
	return n, nil
}

// factsLockClass is the first of the two keys of the PostgreSQL advisory
// lock a device's facts are held under ("FACT"), so the lock shares no key
// with another use of the two-key form. PostgreSQL keeps the two-key and the
// one-key forms apart, so it cannot meet a lock taken by the one-key form.
const factsLockClass = 0x46414354

// LockFactsOfDevice holds the facts of the device whose database ID is
// device for the rest of tx: exclusively for a re-key, shared for a gather.
// A re-key then never runs beside a gather of the same device, which would
// write rows under the previous keys the re-key never read, and two gathers
// still run beside each other as before. Taken before anything of the
// device is read, so what the holder reads is what is committed.
//
// On PostgreSQL it is a transaction advisory lock, released at commit or
// rollback; the device ID is folded into a 32-bit key in the statement, and
// two devices that fold alike only wait for each other.
//
// SQLite has one writer at a time for the whole database, and in WAL mode it
// refuses a write from a transaction whose read another commit overtook, so
// a gather needs nothing more. An exclusive hold takes the database's write
// lock at once, with an UPDATE that matches no row, before anything is read:
// a transaction that has read cannot wait for the write lock (SQLite answers
// it "database is locked" at once, so two readers never wait on each
// other), while one that has not yet read waits out the busy timeout for it
// like any first write, and then reads what the writer before it committed.
func (tx *Tx) LockFactsOfDevice(ctx context.Context, device int, exclusive bool) error {
	var query string
	var args []any
	switch {
	case tx.driver.Dialect() == dialect.Postgres && exclusive:
		query, args = "SELECT pg_advisory_xact_lock($1, CAST(CAST($2 AS bigint) % 2147483647 AS integer))", []any{factsLockClass, int64(device)}
	case tx.driver.Dialect() == dialect.Postgres:
		query, args = "SELECT pg_advisory_xact_lock_shared($1, CAST(CAST($2 AS bigint) % 2147483647 AS integer))", []any{factsLockClass, int64(device)}
	case exclusive:
		// No row has a negative id, so nothing is written.
		query, args = "UPDATE "+fact.Table+" SET "+fact.FieldID+" = "+fact.FieldID+" WHERE "+fact.FieldID+" < 0", []any{}
	default:
		return nil
	}
	if err := tx.driver.Exec(ctx, query, args, nil); err != nil {
		return fmt.Errorf("ent: holding a device's facts: %w", err)
	}
	return nil
}

// rekeyOne runs one compare-and-swap UPDATE b of a single row inside tx: one
// row changed, or ErrFactRekeyRaced. what names the row's kind for an error.
func (tx *Tx) rekeyOne(ctx context.Context, b *entsql.UpdateBuilder, what string) error {
	query, args := b.Query()
	if err := b.Err(); err != nil {
		return fmt.Errorf("ent: re-keying a %s: %w", what, err)
	}
	var res stdsql.Result
	if err := tx.driver.Exec(ctx, query, args, &res); err != nil {
		return fmt.Errorf("ent: re-keying a %s: %w", what, err)
	}
	n, err := res.RowsAffected()
	if err != nil {
		return fmt.Errorf("ent: re-keying a %s: %w", what, err)
	}
	if n != 1 {
		return fmt.Errorf("%w (a %s)", ErrFactRekeyRaced, what)
	}
	return nil
}
